        t("/@word/personShipping"),
        t("/catalog/person/personAddress"),
        t("/catalog/person/personAddress.street"),
      ),
      width: "25ch",
      value: ( row ) => row.person_address_street,
    },
    {
      id: "person_address_number",
      group:"personShipping",
      label: utils.cellHeader(
        t("/@word/personShipping"),
        t("/catalog/person/personAddress"),
